import{e as t,f as a,n as d}from"./index-DBAqsMek.js";const p={async mount(e){await o(e)}};async function o(e){e.innerHTML='<div class="rrr-loading">Loading integration status…</div>';const n=await t("/api/mobile/v1/rrr/integrations"),r=n.ok?(n.data.integrations||[]).find(i=>i.type==="ebioserver"):null;e.innerHTML=`<main class="rrr-page rrr-detail"><header class="rrr-header"><button id="rrr-back">←</button><div class="rrr-brand"><b>RRR</b><span>Integrations</span></div></header><h1>eSSL eBioServer</h1><p>Your phone manages the connection through RRR. eBioServer credentials stay on the gym PC.</p><section class="rrr-panel"><h2>${a(r?.status||"Not configured")}</h2><p>${r?.device_serial?`Device: ${a(r.device_serial)}`:"Pair the eBioServer Bridge from the licensed gym PC."}</p><p>Commissioning: ${a(r?.commissioning_status||"not started")} · ${r?.records_synced||0} records synced · ${r?.unmapped_records||0} unmapped</p><button id="rrr-pair">Generate pairing code</button><div id="rrr-pair-code"></div>${r?.commissioning_status==="attendance_verified"&&!r?.commands_enabled?'<button id="rrr-commission">Enable after supervised door test</button>':""}</section></main>`,e.querySelector("#rrr-back")?.addEventListener("click",()=>d.switchTab("dashboard")),e.querySelector("#rrr-pair")?.addEventListener("click",async()=>{const i=await t("/api/mobile/v1/rrr/integrations/ebioserver/pairing",{method:"POST",body:{}}),s=e.querySelector("#rrr-pair-code");s.textContent=i.ok?`Pairing code: ${i.data.pairing_code} (expires ${new Date(i.data.expires_at).toLocaleTimeString()})`:"Could not create pairing code."}),e.querySelector("#rrr-commission")?.addEventListener("click",async()=>{if(!confirm("Confirm that a supervised physical door test passed."))return;(await t(`/api/mobile/v1/rrr/integrations/${r.id}/commission`,{method:"POST",body:{physical_test_passed:!0}})).ok&&o(e)})}export{p as default};
